/** Visual timeline only. Values are not validated flight or propulsion performance. */
export const ARRIVAL=Object.freeze({touchdown:5.8,settled:6.8,open:10.2,control:15,startAltitude:34,exitZ:-9.4});
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v)),smooth=v=>{v=clamp(v);return v*v*(3-2*v);};
export function arrivalPose(time){const t=Math.max(0,time),p=clamp(t/ARRIVAL.touchdown),settle=clamp((t-ARRIVAL.touchdown)/(ARRIVAL.settled-ARRIVAL.touchdown)),landed=t>=ARRIVAL.touchdown,done=t>=ARRIVAL.control;return{phase:t<ARRIVAL.settled?'landing':done?'explore':'deploy',altitude:landed?.08*Math.sin(Math.PI*settle)*(1-settle):ARRIVAL.startAltitude*(1-smooth(p)),offsetX:landed?0:4*(1-smooth(p)),offsetZ:landed?0:3*(1-smooth(p)),gear:smooth((t-.3)/2.4),compression:landed&&!done?.12+.7*Math.sin(Math.PI*settle)*Math.exp(-settle*1.2):done?.12:0,thrust:!landed?.78-.24*p:t<ARRIVAL.touchdown+.35?.54*(1-(t-ARRIVAL.touchdown)/.35):0,deployment:smooth((t-ARRIVAL.settled)/(ARRIVAL.open-ARRIVAL.settled)),exit:smooth((t-ARRIVAL.open)/(ARRIVAL.control-ARRIVAL.open)),robotVisible:t>ARRIVAL.settled+.65,complete:done};}
